using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// Non-static class — services are injected via the constructor.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool(ReadOnly = true), Description("List all users from the REST API.")]
    public async Task<string> ListUsers(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing users");
        var users = await httpClient.GetFromJsonAsync<JsonElement>(
            "/users", cancellationToken);
        return JsonSerializer.Serialize(users, JsonOptions);
    }

    [McpServerTool(ReadOnly = true), Description("Get a single user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID (e.g. 1)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting user {Id}", id);
        var response = await httpClient.GetAsync($"/users/{id}", cancellationToken);
        if (!response.IsSuccessStatusCode)
        {
            return $"Error: user {id} not found (HTTP {(int)response.StatusCode})";
        }

        var user = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(user, JsonOptions);
    }

    [McpServerTool, Description("Create a new user with the given name and email.")]
    public async Task<string> CreateUser(
        [Description("Full name of the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating user {Name}", name);
        var payload = new { name, email };
        var response = await httpClient.PostAsJsonAsync("/users", payload, cancellationToken);
        response.EnsureSuccessStatusCode();

        var created = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(created, JsonOptions);
    }
}

